INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2745099', 'Oruanui eruption', 'The Oruanui eruption (also known as the Kawakawa eruption or Kawakawa/Oruanui event) of Taupō Volcano in New Zealand around 25,700 years before present was the world''s most recent supereruption, and its largest phreatomagmatic eruption characterised to date.', -26000, NULL, NULL, NULL, NULL, NULL, 'millennium', '26th millennium BCE', 50, 'https://en.wikipedia.org/wiki/Oruanui_eruption'),
  ('Q1192398', 'Musket Wars', 'The Musket Wars were a series of as many as 3,000 battles and raids fought throughout New Zealand (including the Chatham Islands) among Māori between 1806 and 1845, after Māori first obtained muskets and then engaged in an intertribal arms race in order to gain territory or seek revenge for past defeats. The battles resulted in the deaths of between 20,000 and 40,000 people and the enslavement of tens of thousands of Māori and significantly altered the rohe, or tribal territorial boundaries, before the signing of the Treaty of Waitangi in 1840.', 1807, NULL, NULL, 1842, NULL, NULL, 'year', '1807–1842', 60, 'https://en.wikipedia.org/wiki/Musket_Wars'),
  ('Q895905', 'Boyd massacre', 'The Boyd massacre occurred in December 1809 when Māori of Ngāti Pou from Whangaroa Harbour in northern New Zealand killed and ate between 66 and 70 European passengers and crew members from the British brigantine Boyd. This was the highest number of Europeans killed by Māori in a single event in New Zealand.', 1809, 12, NULL, NULL, NULL, NULL, 'month', 'December 1809', 41, 'https://en.wikipedia.org/wiki/Boyd_massacre'),
  ('Q1510144', 'Wairau Affray', 'The Wairau Affray of 17 June 1843, also called the Wairau Massacre and the Wairau Incident, was the first serious clash of arms between British settlers and Māori in New Zealand after the signing of the Treaty of Waitangi and the only one to take place in the South Island. The incident was sparked when a magistrate and a representative of the New Zealand Company, who held a deed to land in the Wairau Valley in the Nelson Province in the north of the South Island, led a group of European settlers to attempt to arrest Ngāti Toa chiefs Te Rauparaha and Te Rangihaeata.', 1843, 6, 17, NULL, NULL, NULL, 'day', '17 June 1843', 43, 'https://en.wikipedia.org/wiki/Wairau_Affray'),
  ('Q949495', 'Battle of Ohaeawai', 'The Battle of Ōhaeawai, part of the Flagstaff War, was fought in July 1845 at Ōhaeawai in Northland, New Zealand. The battle was between British forces and their allies from the local Ngāpuhi tribe of Māori on one side, and other Ngāpuhi, led by Te Ruki Kawiti, a prominent rangatira (chief), on the other side.', 1845, 7, NULL, NULL, NULL, NULL, 'month', 'July 1845', 34, 'https://en.wikipedia.org/wiki/Battle_of_%C5%8Chaeawai'),
  ('Q1545405', 'New Zealand Wars', 'The New Zealand Wars (Māori: ngā pakanga o Aotearoa) took place from 1845 to 1872 between the New Zealand colonial government and allied Māori on one side, and Māori and Māori-allied settlers on the other. The conflicts did not divide neatly along ethnic lines, as Māori fought on both sides and individuals of European origin also fought alongside Māori forces.', 1845, NULL, NULL, 1872, NULL, NULL, 'year', '1845–1872', 62, 'https://en.wikipedia.org/wiki/New_Zealand_Wars'),
  ('Q929108', '1848 Marlborough earthquake', 'The 1848 Marlborough earthquake was a Mw 7.5 earthquake that occurred at 1:40 a.m. on 16 October 1848 with an epicentre in the Marlborough region of the South Island of New Zealand.', 1848, 10, 16, NULL, NULL, NULL, 'day', '16 October 1848', 39, 'https://en.wikipedia.org/wiki/1848_Marlborough_earthquake'),
  ('Q16685818', '1886 eruption of Mount Tarawera', 'A violent volcanic eruption occurred in the early hours of 10 June 1886 at Mount Tarawera, near Rotorua on New Zealand''s North Island. The eruption reached an estimated volcanic explosivity index (VEI) of 5 and killed an estimated 120 people, making it the largest and deadliest in New Zealand during the past 500 years, a period that includes the entirety of European history in New Zealand.', 1886, 6, 10, NULL, NULL, NULL, 'day', '10 June 1886', 43, 'https://en.wikipedia.org/wiki/1886_eruption_of_Mount_Tarawera'),
  ('Q1486364', '1888 North Canterbury earthquake', 'The 1888 North Canterbury earthquake occurred at 4:10 am on 1 September following a sequence of foreshocks that started the previous evening, and whose epicentre was in the North Canterbury region of the South Island of New Zealand. The epicentre was approximately 35 kilometres (22 mi) west of Hanmer.', 1888, 9, 1, NULL, NULL, NULL, 'day', '1 September 1888', 34, 'https://en.wikipedia.org/wiki/1888_North_Canterbury_earthquake'),
  ('Q4557855', '1901 Cheviot earthquake', 'The 1901 Cheviot earthquake occurred at 07:47 NZT on 16 November 1901 (20:15 15 November UTC) with an estimated magnitude of 6.9, centred near the township of Cheviot in the Canterbury region of New Zealand.', 1901, 11, 16, NULL, NULL, NULL, 'day', '16 November 1901', 39, 'https://en.wikipedia.org/wiki/1901_Cheviot_earthquake'),
  ('Q1225445', '1929 Murchison earthquake', 'The 1929 Murchison earthquake occurred at 10:17 am on 17 June. It struck the Murchison region of the South Island, with an estimated magnitude of 7.3, and was felt throughout New Zealand.', 1929, 6, 17, NULL, NULL, NULL, 'day', '17 June 1929', 37, 'https://en.wikipedia.org/wiki/1929_Murchison_earthquake'),
  ('Q719883', 'Statute of Westminster 1931', 'The Statute of Westminster 1931 (22 & 23 Geo. 5.', 1931, NULL, NULL, NULL, NULL, NULL, 'year', '1931', 71, 'https://en.wikipedia.org/wiki/Statute_of_Westminster_1931'),
  ('Q722402', '1931 Hawke''s Bay earthquake', 'The 1931 Hawke''s Bay earthquake, also known as the Napier earthquake, occurred in New Zealand at 10:47 am on 3 February, killing 256, injuring thousands and devastating the Hawke''s Bay region. It remains New Zealand''s deadliest natural disaster.', 1931, 2, 3, NULL, NULL, NULL, 'day', '3 February 1931', 43, 'https://en.wikipedia.org/wiki/1931_Hawke''s_Bay_earthquake'),
  ('Q713529', 'Battle of the River Plate', 'The Battle of the River Plate was fought in the South Atlantic on 13 December 1939 as the first British naval battle of the Second World War. The Kriegsmarine heavy cruiser Admiral Graf Spee, commanded by Captain Hans Langsdorff, engaged a Royal Navy squadron, commanded by Commodore Henry Harwood, comprising the light cruisers HMS Ajax, HMNZS Achilles (on loan to the New Zealand Division) and the heavy cruiser HMS Exeter.', 1939, 12, 13, NULL, NULL, NULL, 'day', '13 December 1939', 71, 'https://en.wikipedia.org/wiki/Battle_of_the_River_Plate'),
  ('Q1668495', 'Battle of Kolombangara', 'The Battle of Kolombangara (Japanese: コロンバンガラ島沖海戦) (also known as the Second Battle of Kula Gulf) was a naval battle of the Pacific campaign of World War II, fought on the night of 12/13 July 1943, off the northeastern coast of Kolombangara in the Solomon Islands. The battle took place during the early stages of the New Georgia campaign when an Imperial Japanese Navy force, carrying reinforcements south to Vila, Solomon Islands, was intercepted by a task force of U.S. and New Zealand light cruisers and destroyers.', 1943, 7, 12, 1943, 7, 13, 'day', '12 July 1943 – 13 July 1943', 51, 'https://en.wikipedia.org/wiki/Battle_of_Kolombangara'),
  ('Q16470', 'Normandy landings', 'The Normandy landings were the landing operations and associated airborne operations on 6 June 1944 of the Allied invasion of Normandy in Operation Overlord during the Second World War. Codenamed Operation Neptune and often referred to as D-Day (after the military term), it is the largest seaborne invasion in history.', 1944, 6, 6, 1944, 8, 29, 'day', '6 June 1944 – 29 August 1944', 81, 'https://en.wikipedia.org/wiki/Normandy_landings'),
  ('Q192660', 'Battle of Okinawa', 'The Battle of Okinawa (Japanese: 沖縄戦, Hepburn: Okinawa-sen), codenamed Operation Iceberg, was a major battle of the Pacific War fought on the island of Okinawa by the United States Army and United States Marine Corps forces against the Imperial Japanese Army. The initial invasion of Okinawa on 1 April 1945 was the largest amphibious assault in the Pacific Theater of World War II. The Kerama Islands surrounding Okinawa were preemptively captured on 26 March 1945 by the U.S. Army 77th Infantry Division.', 1945, NULL, NULL, 1945, 6, 23, 'year', '1945', 77, 'https://en.wikipedia.org/wiki/Battle_of_Okinawa'),
  ('Q665554', 'Japanese Instrument of Surrender', 'The Japanese Instrument of Surrender was the printed agreement that formalized the surrender of Japan, marking the end of hostilities in World War II. It was signed by representatives from Japan and from the Allied nations: the United States, China, the United Kingdom, the Soviet Union, Australia, Canada, France, the Netherlands, and New Zealand. The signing took place on the deck of USS Missouri in Tokyo Bay just after 09:00 Japan Standard Time (JST) and took effect at 09:25 JST on 2 September 1945.', 1945, 9, 2, NULL, NULL, NULL, 'day', '2 September 1945', 69, 'https://en.wikipedia.org/wiki/Japanese_Instrument_of_Surrender'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q259526', 'Battle of Long Tan', 'The Battle of Long Tan (18–21 August 1966) took place in a rubber plantation near Long Tân, in Phước Tuy Province, South Vietnam, during the Vietnam War. The action was fought between Viet Cong (VC) and People''s Army of Vietnam (PAVN) units on one side and elements of the 1st Australian Task Force (1 ATF) on the other.', 1966, 8, 18, NULL, NULL, NULL, 'day', '18 August 1966', 53, 'https://en.wikipedia.org/wiki/Battle_of_Long_Tan'),
  ('Q82542', 'Tet Offensive', 'The Tet Offensive was both a major escalation and one of the largest military campaigns of the Vietnam War. The North Vietnamese People''s Army of Vietnam (PAVN) and the Viet Cong (VC) launched a surprise attack on 30 and 31 January 1968 against the forces of the South Vietnamese Army of the Republic of Vietnam (ARVN), the United States Armed Forces and their allies, targeting military and civilian command and control centers throughout South Vietnam.', 1968, 1, 30, 1968, 9, 23, 'day', '30 January 1968 – 23 September 1968', 72, 'https://en.wikipedia.org/wiki/Tet_Offensive'),
  ('Q5933027', '1968 Inangahua earthquake', 'The 1968 Inangahua earthquake struck 25 kilometres (16 mi) west of Murchison, New Zealand, near the small town of Inangahua Junction at 5:24 am NZDT on 24 May 1968. The earthquake had a moment magnitude of 7.1, a local magnitude of 6.7, a surface-wave magnitude of 7.4 and a maximum Mercalli intensity of X (Extreme).', 1968, 5, 23, NULL, NULL, NULL, 'day', '23 May 1968', 39, 'https://en.wikipedia.org/wiki/1968_Inangahua_earthquake'),
  ('Q8740', 'Vietnam War', 'The Vietnam War (c. 1955 – 30 April 1975) was an armed conflict in Vietnam, Laos, and Cambodia fought between North Vietnam (Democratic Republic of Vietnam) and South Vietnam (Republic of Vietnam) and their allies. North Vietnam was supported by the Soviet Union and China, while South Vietnam was supported by the United States and other anti-communist nations.', 1975, 4, 30, 1975, 4, 30, 'day', '30 April 1975', 97, 'https://en.wikipedia.org/wiki/Vietnam_War'),
  ('Q1284366', '1987 Edgecumbe earthquake', 'The 1987 Edgecumbe earthquake measured 6.5 on the moment magnitude scale and struck the Bay of Plenty region of New Zealand at 1.42 pm on 2 March. The hypocentre was at a shallow depth of 8 km.', 1987, 3, 2, NULL, NULL, NULL, 'day', '2 March 1987', 37, 'https://en.wikipedia.org/wiki/1987_Edgecumbe_earthquake'),
  ('Q473868', 'Aramoana massacre', 'The Aramoana massacre was a mass shooting that occurred on 13 November 1990 in the small seaside township of Aramoana, northeast of Dunedin, New Zealand. Resident David Gray killed 13 people, including local police Sergeant Stewart Guthrie, one of the first responders to the reports of a shooting, after a verbal dispute between Gray and his next-door neighbour.', 1990, 11, 14, 1990, 11, 14, 'day', '14 November 1990', 39, 'https://en.wikipedia.org/wiki/Aramoana_massacre'),
  ('Q4770648', 'Ansett New Zealand Flight 703', 'Ansett New Zealand Flight 703 was a scheduled flight from Auckland to Palmerston North. On 9 June 1995, the de Havilland Canada Dash 8-100 aircraft crashed into the Tararua Range on approach to Palmerston North.', 1995, 6, 9, NULL, NULL, NULL, 'day', '9 June 1995', 45, 'https://en.wikipedia.org/wiki/Ansett_New_Zealand_Flight_703'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q1527224', '2007 Gisborne earthquake', 'The 2007 Gisborne earthquake occurred under the Pacific Ocean about 50 kilometres (31 mi) off the eastern coast of New Zealand''s North Island at 8:55 pm NZDT on 20 December. With a moment magnitude of 6.7 and maximum Mercalli intensity of VII (Very Strong), the tremor affected the city of Gisborne and was felt widely throughout the country, from Auckland in the north to Dunedin in the south.', 2007, 12, 20, NULL, NULL, NULL, 'day', '20 December 2007', 41, 'https://en.wikipedia.org/wiki/2007_Gisborne_earthquake'),
  ('Q1131956', '2009 Fiordland earthquake', 'A Mw 7.8 earthquake struck a remote region of Fiordland, New Zealand, on 15 July 2009 at 21:22 local time (09:22 UTC). It had an initially–reported depth of 12 km (7.5 mi), and an epicentre near Dusky Sound in Fiordland National Park, which is 160 km (99 mi) north-west of Invercargill.', 2009, 7, 15, NULL, NULL, NULL, 'day', '15 July 2009', 41, 'https://en.wikipedia.org/wiki/2009_Dusky_Sound_earthquake'),
  ('Q750144', '2010 Canterbury earthquake', 'The 2010 Canterbury earthquake (also known as the Darfield earthquake) struck the South Island of New Zealand with a moment magnitude of 7.1 at 4:35 am local time on 4 September, and had a maximum perceived intensity of X (Extreme) on the Mercalli intensity scale. Some damaging aftershocks followed the main event, the strongest of which was a magnitude 6.3 shock known as the Christchurch earthquake that occurred nearly six months later on 22 February 2011.', 2010, 9, 3, NULL, NULL, NULL, 'day', '3 September 2010', 63, 'https://en.wikipedia.org/wiki/2010_Canterbury_earthquake'),
  ('Q12063953', 'New Zealand flag debate', 'The New Zealand flag debate is a question over whether the national flag of New Zealand should be changed. For several decades, alternative designs have been proposed, with varying degrees of support.', 2010, NULL, NULL, NULL, NULL, NULL, 'decade', '2010s', 37, 'https://en.wikipedia.org/wiki/New_Zealand_flag_debate'),
  ('Q151850', 'February 2011 Christchurch earthquake', 'A major earthquake occurred in Christchurch on Tuesday 22 February 2011 at 12:51 p.m. local time (23:51 UTC, 21 February).', 2011, 2, 22, NULL, NULL, NULL, 'day', '22 February 2011', 70, 'https://en.wikipedia.org/wiki/2011_Christchurch_earthquake'),
  ('Q2801192', 'June 2011 Christchurch earthquake', 'The June 2011 Christchurch earthquake was a shallow magnitude 6.0 Mw earthquake that occurred on 13 June 2011 at 14:20 NZST (02:20 UTC). It was centred at a depth of 7 km (4.3 mi), about 5 km (3 mi) south-east of Christchurch, which had previously been devastated by a magnitude 6.2 MW earthquake in February 2011.', 2011, 6, 13, NULL, NULL, NULL, 'day', '13 June 2011', 51, 'https://en.wikipedia.org/wiki/June_2011_Christchurch_earthquake'),
  ('Q21027080', '2015–2016 New Zealand flag referendums', 'Two referendums were held by the New Zealand Government in November/December 2015 and March 2016 to determine the nation''s flag. In the first referendum, voters chose their favourite alternative flag design.', 2015, 12, 11, NULL, NULL, NULL, 'day', '11 December 2015', 57, 'https://en.wikipedia.org/wiki/2015%E2%80%932016_New_Zealand_flag_referendums'),
  ('Q27850765', '2016 North Canterbury earthquake', 'The 2016 Kaikōura earthquake was a Mw 7.8 earthquake in the South Island of New Zealand that occurred two minutes after midnight on 14 November 2016 NZDT (11:02 on 13 November UTC). Ruptures occurred on multiple faults and the earthquake has been described as the "most complex earthquake ever studied".', 2016, 11, 13, NULL, NULL, NULL, 'day', '13 November 2016', 57, 'https://en.wikipedia.org/wiki/2016_Kaik%C5%8Dura_earthquake'),
  ('Q62066211', 'Christchurch mosque shootings', 'On 15 March 2019, two consecutive terrorist mass shootings took place in Christchurch, New Zealand. They were committed during Friday prayer, first at the Al Noor Mosque in Riccarton at 1:40 p.m., and shortly afterwards at 1:52 p.m.', 2019, 3, 15, NULL, NULL, NULL, 'day', '15 March 2019', 82, 'https://en.wikipedia.org/wiki/Christchurch_mosque_shootings'),
  ('Q77929275', '2019 Whakaari / White Island eruption', 'On 9 December 2019, Whakaari / White Island, an active stratovolcano island in New Zealand''s northeastern Bay of Plenty region, explosively erupted. The island was a popular tourist destination, known for its volcanic activity, and 47 people were on the island at the time.', 2019, 12, 9, NULL, NULL, NULL, 'day', '9 December 2019', 50, 'https://en.wikipedia.org/wiki/2019_Whakaari_%2F_White_Island_eruption'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q105758009', '2021 Kermadec Islands earthquake', 'The 2021 Kermadec Islands earthquakes were a series of earthquakes with magnitudes of 8.1 and 7.4 that occurred at 19:28:31 UTC on 4 March 2021. The epicentres were located southeast of Raoul Island in the Kermadec Islands, part of the New Zealand outlying islands.', 2021, 3, 5, NULL, NULL, NULL, 'day', '5 March 2021', 39, 'https://en.wikipedia.org/wiki/2021_Kermadec_Islands_earthquakes');
